# The apps a person has let into their account, and the button that lets
# them out again (generated by maquina:oauth).
class ConnectedApplicationsController < ApplicationController
  before_action :require_mcp_enabled

  # GET connected_apps_path (/settings/connected_apps unless --prefix said otherwise)
  def index
    @connected_applications = ConnectedApplication.for(Current.user)
  end

  # DELETE connected_app_path(oauth_client)
  def destroy
    connected_application = ConnectedApplication.find(Current.user, params[:id])
    connected_application.revoke!

    Rails.logger.info "[OAUTH] #{connected_application.client.client_id} disconnected by #{Current.user.email_address}"
    redirect_to connected_apps_path, status: :see_other,
      notice: t("flash.connected_applications.destroyed", name: connected_application.client.client_name)
  end

  private

  def require_mcp_enabled
    head :not_found unless Mcp.enabled_for?(Current.user)
  end
end
